entries[416290] = { ["name"] = "Ewige Verderbnis", ["text"] = "Unbegrenzte Reichweite\nSofort\nDeios überzieht Nozdormu mit verderbter Bronzemagie, lässt alle 2 Sek. arkane Artillerie auf die Umgebung niedergehen und fügt allen Spielercharakteren zusätzlich 1745604 Arkanschaden zu. Hält 4 Sek. lang an.\n\nDie kleineren Blitze fügen Zielen innerhalb von 3 Metern 3636674 Arkanschaden zu und die größeren fügen Zielen innerhalb von 8 Metern 7273348 Arkanschaden zu." }
