entries[416506] = { ["name"] = "Entfesseltes Inferno", ["text"] = "Während 'Einäschern' aktiv ist, verursachen Eure Zauber 'Feuerball', 'Pyroschlag', 'Feuerschlag', 'Versengen' und 'Phönixflammen' 70% mehr Schaden und verringern die Abklingzeit von 'Einäschern' um 1.25 Sek.\n\nWährend 'Einäschern' aktiv ist, verursacht 'Flammenstoß' 35% mehr Schaden und verringert die Abklingzeit von 'Einäschern' für jeden kritischen Treffer um 0.25 Sek., bis maximal 1.25 Sek." }
