entries[416682] = { ["name"] = "Beherzte Kurzklinge", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (12), Silberbarren (8), Goldbarren (2), Verdichteter Schleifstein (4)\nEntdeckung:\nScholomance\n\nBeherzte Kurzklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]Haltbarkeit 85 / 85" }
entries[416683] = { ["name"] = "Tapfere Kurzklinge", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (12), Silberbarren (2), Goldbarren (8), Verdichteter Schleifstein (4)\nEntdeckung:\nScholomance\n\nTapfere Kurzklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n1 - 3 Schaden Geschwindigkeit 2.60\n(0.8 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 85 / 85" }
entries[416684] = { ["name"] = "Magierbann-Nexus", ["text"] = "Wirken in 3.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nGroße ewige Essenz (20), Rechtschaffene Kugel , Dunkelrune (4), Einfaches Holz\nEntdeckung:\nScholomance\n\nMagierbann-Nexus\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+1 Arkanwiderstand\n+1 Feuerwiderstand\n+1 Frostwiderstand" }
entries[416685] = { ["name"] = "Smokeys Feuerschleuder", ["text"] = "Wirken in 3.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nGroßer glänzender Splitter (8), Essenz des Feuers , Einfaches Holz\nEntdeckung:\nScholomance\n\nSmokeys Feuerschleuder\nWird beim Anlegen gebunden\nDistanz Zauberstab\n1 - 3 Feuerschaden Geschwindigkeit 2.00\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 75 / 75" }
entries[416686] = { ["name"] = "Sturmbetrachter", ["text"] = "Wirken in 3.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nAzerothischer Diamant (2), Großer glänzender Splitter (18), Verzauberter Thoriumbarren (12), Leichte Feder (4)\nEntdeckung:\nScholomance\n\nSturmbetrachter\nWird beim Anlegen gebunden\nDistanz Zauberstab\n1 - 3 Naturschaden Geschwindigkeit 2.00\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\nHaltbarkeit 90 / 90" }
entries[416687] = { ["name"] = "Hochheiliger Wächter", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtsilberbarren (28), Rechtschaffene Kugel (5)\nEntdeckung:\nScholomance\n\nHochheiliger Wächter\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\nHaltbarkeit 100 / 100" }
entries[416688] = { ["name"] = "Giftschlitzer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (2), Verdichteter Schleifstein (2), Gewaltiger Smaragd (6), Riesiger Giftbeutel (10)\nEntdeckung:\nScholomance\n\nGiftschlitzer\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nAnlegen: Vergiftet das Ziel und fügt 20 Sek. lang alle 2 Sek. 0 Naturschaden zu." }
entries[416689] = { ["name"] = "Schädelsteinknüttel", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nBogenlichtschraubenschlüssel , Surrendes bronzenes Dingsda (5), Echtsilberbarren (6), Essenz des Untodes (6), Thoriumapparat (3)\nEntdeckung:\nScholomance\n\nSchädelsteinknüttel\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+10 Intelligenz\n+3 Ausdauer\n+ 1 Vielseitigkeit\nHaltbarkeit 75 / 75" }
entries[416690] = { ["name"] = "Wandererwegweiser", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nBronzebarren (30), Großer Opal (2)\nEntdeckung:\nScholomance\n\nWandererwegweiser\nWird beim Anlegen gebunden\nZweihändig Stab\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+16 Intelligenz\n+5 Ausdauer\nHaltbarkeit 85 / 85" }
entries[416691] = { ["name"] = "Runderneuerter Läuterer", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEmpfindlicher Arkanitwandler (4), Arkanitbarren (6), Thoriumröhre (2), Tödliches Zielfernrohr , Instabiler Auslöser\nEntdeckung:\nScholomance\n\nRunderneuerter Läuterer\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 10 Schaden Geschwindigkeit 3.00\n(2.5 Schaden pro Sekunde)\n+4 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\nHaltbarkeit 120 / 120" }
entries[416692] = { ["name"] = "Geweihter Lederhut", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nVerzaubertes Leder (20), Geschmeidiger unverwüstlicher Balg (6), Blauer Farbstoff (6), Runenfaden (6)\nEntdeckung:\nScholomance\n\nGeweihter Lederhut\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+5 Ausdauer\n+ 3 Vielseitigkeit\nHaltbarkeit 85 / 85" }
