entries[417489] = { ["name"] = "Wintersegen", ["text"] = "Euer Tempo ist um 8% erhöht.\n\nIhr erhaltet 10% mehr Tempo aus allen Quellen." }
entries[417490] = { ["name"] = "Benebelnder Aufprall", ["text"] = "Unbegrenzte Reichweite\nSofort\nEuer 'Kometenhagel' wendet nun 'Benebelnder Aufprall' an, was den Schaden, den Gegner durch Euch erleiden, 6 Sek. lang um 6% erhöht. Zusätzlich hat 'Hagel' bei jedem Treffer eine Chance von 25%, einen eisigen Kometen herabzubeschwören, der auf Euer Ziel sowie Gegner in der Nähe schmettert und ihnen (33.327% der Zaubermacht) Frostschaden zufügt." }
entries[417491] = { ["name"] = "Kryopathie", ["text"] = "Jedes Mal, wenn Ihr 'Eisige Finger' verbraucht, erhöht sich der Schaden Eures nächsten Einsatzes von 'Froststrahl' um 5%. Bis auf 50% stapelbar. 'Eisige Adern' gewährt sofort 10 Stapel." }
